                             // чтобы не загромождать FAB-меню. Конструктор всё ещё может скрыть любую.
                             Row(verticalAlignment = Alignment.CenterVertically) {
                                 Text(
                                     if (isAutoRead) "Стоп авточтения  " else "Авточтение  ",
