input.content:
const fs = require('fs');
const { JSDOM } = require('/tmp/opencode/node_modules/jsdom');

const html = `<!DOCTYPE html><html><body>
  <header class="reader-header" style="position:sticky;top:0;z-index:500">← том 1 глава 0 →</header>
  <img class="manga-page" src="p1.jpg" alt="">
  <div style="position:fixed;bottom:0;left:0;right:0;z-index:99999" class="c-9f3a2 x-pop">
    +1 В паках больше выбора. Теперь можно выбрать 1 карту из 4 предложенных
  </div>
  <iframe src="https://cdn.example.com/_ads/banner.js" style="position:fixed;bottom:80px;z-index:90"></iframe>
  <iframe src="https://serve.adsterra.com/x" style="position:fixed;bottom:120px;z-index:91"></iframe>
  <div class="telegram-promo" style="position:fixed;bottom:200px;z-index:95">Мы в telegram</div>
  <div class="ins adsbygoogle" style="position:fixed;bottom:240px;z-index:96">ad</div>
  <footer class="reader-footer" style="position:sticky;bottom:0;z-index:600">навигация страниц</footer>
  <div id="promo-code" style="position:fixed;bottom:300px;z-index:97">Промокод NEW2026</div>
  <img class="manga-page" src="p2.jpg" alt="">
  <p class="manga-caption">ВЫ ЗНАЛИ, ЧТО НАША ЛЮБОВЬ ПРЕДРЕШЕНА СУДЬБОЙ?</p>
  <div class="adventure-slider">контент слайдера (adv в имени, но есть slide)</div>
</body></html>`;

const dom = new JSDOM(html, {
  runScripts: 'dangerously',
  pretendToBeVisual: true,
  url: 'https://mangabuff.ru/read/1/0',
});
const { window } = dom;
const { document } = window;

// jsdom отдаёт нулевые rect'ы — раздаём размеры вручную по смыслу узла
const rects = {
  'reader-header': [0, 0, 720, 60],
  'reader-footer': [0, 1000, 720, 1098],
  'c-9f3a2 x-pop': [10, 940, 710, 1060],
  'promo-code': [10, 800, 710, 860],
  'telegram-promo': [10, 760, 710, 830],
  'ins adsbygoogle': [10, 720, 710, 790],
};
let rectCalls = 0;
window.Element.prototype.getBoundingClientRect = function () {
  rectCalls++;
  const r = rects[this.className] || rects[this.id];
  const w = this.tagName === 'IMG' ? 720 : 0;
  const h = this.tagName === 'IMG' ? 900 : 0;
  const [l, t, rr, bb] = r || [0, 0, w, h];
  return { left: l, top: t, right: rr, bottom: bb, width: rr - l, height: bb - t };
};

inject();
async function inject() {
  window.eval(fs.readFileSync('/tmp/opencode/adblock.js', 'utf8'));
  await new Promise((r) => setTimeout(r, 600));

  const alive = (sel) => document.querySelectorAll(sel).length;
  const checks = [
    ['промо-карточка «В паках больше выбора»', () => alive('.c-9f3a2') === 0],
    ['iframe /_ads/', () => alive('iframe[src*="/_ads/"]') === 0],
    ['iframe adsterra', () => alive('iframe[src*="adsterra"]') === 0],
    ['telegram-promo', () => alive('.telegram-promo') === 0],
    ['ins.adsbygoogle', () => alive('ins.adsbygoogle') === 0],
    ['#promo-code (промокод)', () => alive('#promo-code') === 0],
    ['Шапка ридера уцелела', () => alive('.reader-header') === 1],
    ['Подвал ридера уцелел', () => alive('.reader-footer') === 1],
    ['Картинки манги уцелели', () => alive('img.manga-page') === 2],
    ['Подпись страницы уцелела', () => document.body.textContent.includes('ВЫ ЗНАЛИ, ЧТО НАША ЛЮБОВЬ')],
    ['Слайдер (adv+slide) уцелел', () => alive('.adventure-slider') === 1],
  ];

  let fail = 0;
  for (const [name, ok] of checks) {
    const passed = await ok();
    if (!passed) fail++;
    console.log((passed ? 'PASS' : 'FAIL') + '  ' + name);
  }

  // Динамическая подсыпание рекламы (жалоба: «всё время меняется»)
  const late = document.createElement('div');
  late.className = 'x-rand42';
  late.setAttribute('style', 'position:fixed;bottom:40px;left:0;right:0;z-index:99999');
  late.textContent = 'Новое промо: 1 карту из 4 предложений';
  document.body.appendChild(late);
  await new Promise((r) => setTimeout(r, 700));
  const lateGone = alive('.x-rand42') === 0;
  console.log((lateGone ? 'PASS' : 'FAIL') + '  Поздно подсеянная реклама удалена (MutationObserver)');
  if (!lateGone) fail++;

  // Тумблер выключен — фильтр трогать страницу не должен
  window.__ykAbOn(false);
  const off = document.createElement('div');
  off.className = 'x-off';
  off.setAttribute('style', 'position:fixed;bottom:10px;z-index:99999');
  off.textContent = 'офф-тест';
  document.body.appendChild(off);
  await new Promise((r) => setTimeout(r, 400));
  const stays = alive('.x-off') === 1;
  console.log((stays ? 'PASS' : 'FAIL') + '  AdBlock выключен — реклама остаётся');
  if (!stays) fail++;

  console.log(fail === 0 ? '\nALL TESTS PASSED' : `\n${fail} TEST(S) FAILED`);
  process.exit(fail === 0 ? 0 : 1);
}

