/**
 * Доминирующий язык текста кадра по письменности: "ru"/"en"/"ja"/"ko"/"zh",
 * "" — букв не нашлось. Нужен, чтобы при источнике «auto» решить,
 * надо ли переводить: язык реплик из настроек (et alon «ru») врал на
 * китайской манхуа, и перевод молча выключался.
 */
fun dominantLanguage(texts: List<String>): String {
    var cyr = 0
    var lat = 0
    var kana = 0
    var hangul = 0
    var han = 0
    for (t in texts) {
        for (ch in t) {
            when {
                ch in '\u0400'..'\u04FF' -> cyr++
                ch in '\u0041'..'\u005A' || ch in '\u0061'..'\u007A' -> lat++
                ch in '\u3040'..'\u30FF' -> kana++
                ch in '\uAC00'..'\uD7AF' -> hangul++
                ch in '\u4E00'..'\u9FFF' -> han++
            }
        }
    }
    val top = maxOf(cyr, lat, kana, hangul, han)
    if (top == 0) return ""
    return when (top) {
        cyr -> "ru"
        lat -> "en"
        kana -> "ja"
        hangul -> "ko"
        else -> "zh"
    }
}

