```
But recycler.scrollBy from a coroutine — any thread OK (scrollBy must be main thread? RecyclerView.scrollBy can be called from any thread? Not guaranteed; use withContext(Main)).

Put the stepper in the activity's consumer instead, using `v.scrollDownByFraction`-style small fractions. Actually add a public suspend helper in ReaderActivity:

```kotlin
private suspend fun smoothWebtoonScroll(fraction: Float, durationMs: Long) {
    val v = withUIContext { viewModel.state.value.viewer } as? WebtoonViewer ?: return
    val total = withUIContext { binding.root.height }.toFloat().coerceAtLeast(1f)
    val totalPx = total * fraction
    if (totalPx < 1) return
    val steps = (durationMs / 16).toInt().coerceIn(8, 120)
    var done = 0f
    for (s in 1..steps) {
        if (!autoReadActive) return
        val t = s.toFloat() / steps
        val targetPx = totalPx * easeOut(t)   // easeOut = 1-(1-t)^2
        val stepPx = (targetPx - done).toInt()
        done = targetPx
        if (stepPx <= 0) { delay(16); continue }
        withUIContext { v.scrollByPx(stepPx) }  // hmm need a px API
        delay(16)
    }
}
