                }
                OcrHistoryStore.addAutoRead(
                    false,
                    "OCR-кадр таймаут",
                    "${OCR_FRAME_TIMEOUT_MS / 1000}с pageIndex=$pageIndex",
                )
                // Таймаут — это «не смогли», а не «текста нет»: пустой кадр
