            val frameMs = android.os.SystemClock.elapsedRealtime() - tFrame0
            runCatching { prefs.autoReadLastMs(result.ocrModel).set(frameMs.toString()) }
            eu.kanade.tachiyomi.data.ai.AiConsole.ocr(
