private suspend fun requireCurrentSelectionBitmap(
    rect: android.graphics.RectF,
    failureLogMessage: String,
    failureMessageRes: StringResource,
): Bitmap? {
    val croppedBitmap = cropCurrentSelectionBitmap(rect)
    if (croppedBitmap != null) {
        return croppedBitmap
    }

    logcat(LogPriority.WARN) { failureLogMessage }
    withUIContext {
        exitOcrMode()
        toast(failureMessageRes)
    }
    return null
}

/**
 * Перерисовать дерево вьюх читалки.
 *
 * Пометки порядка чтения рисует сама вьюха страницы (координаты регионов
 * лежат в пикселях страницы, а не окна), а invalidate() родителя НЕ
 * помечает потомков грязными — при аппаратном рендере они переиспользуют
 * готовые display list. Поэтому обходим дерево и просим каждую вьюху
 * перерисоваться: так работает и включение/выключение пометок, и появление
 * нового снимка на открытой странице.
 */
private fun invalidateReaderViews(view: View = binding.root) {
    view.invalidate()
    if (view is ViewGroup) {
        for (index in 0 until view.childCount) {
            invalidateReaderViews(view.getChildAt(index))
        }
    }
}

private suspend fun cropCurrentSelectionBitmap(
    rect: android.graphics.RectF,
): Bitmap? = cropCurrentSelectionFrame(rect)?.bitmap

/**
 * Кадр видимой области страницы вместе с его геометрией.
 *
 * Кадр без геометрии — половина записи скриншота: координаты распознанных
 * регионов нормализованы к уменьшенному и обрезанному битмапу кадра, а в
 * книге их нужно вернуть на страницу. Геометрия доступна только когда кадр
 * снят с ОДНОЙ страницы ([frameGeometryOf]).
 */
private suspend fun cropCurrentSelectionFrame(
    rect: android.graphics.RectF,
): ReaderFrameCapture? {
    val captures = resolveSelectionCaptures(rect)
    // Страница может быть ещё не отрисована (или у вебтуна нет разрешимой
    // области выделения) — это обычное состояние, а не ошибка. Раньше здесь
    // бросалось IllegalStateException, и авто-поиск издания при открытии главы
    // (LaunchedEffect) ронял приложение необработанным исключением из корутины.
    if (captures.isEmpty()) {
        logcat(LogPriority.DEBUG) { "Selection not ready for crop, skipping" }
        return null
    }
    val manga = viewModel.manga ?: throw IllegalStateException("Manga unavailable")
    val bitmap = selectionBitmapCropper.cropSelectionBitmap(
        manga = manga,
        captures = captures,
        shape = mihon.data.ocr.ScanShape.fromId(
            uy.kohesive.injekt.Injekt.get<mihon.domain.ocr.service.OcrPreferences>().scanShape().get(),
        ),
    ) ?: return null
    return ReaderFrameCapture(bitmap = bitmap, geometry = frameGeometryOf(captures))
}

/**
 * Какая часть файла страницы попала в кадр, в нормализованных координатах
 * (0..1) плюс размеры самого файла.
 *
 * Размеры берём у вьюхи страницы, потому что [ReaderSelectionCapture.sourceRect]
 * — это прямоугольник в координатах ИМЕННО ЭТОГО файла (вьюха сама
 * разворачивает зум, панораму, поворот и обрезку рамок), а размеры кадра
 * после даунскейла к ним непригодны.
 *
 * null — геометрии нет: кадр склеен из нескольких страниц (экран вебтуна
 * перекрыл границу полос) или страница ещё не отрисована. Тогда запись
 * скриншота остаётся без геометрии, и в книге она просто ничего не рисует.
 */
private fun frameGeometryOf(
    captures: List<ReaderSelectionCapture>,
): AutoReadEngine.OcrFrameGeometry? {
    val capture = captures.singleOrNull() ?: return null
    val source = (capture.bitmapSource as? ReaderPageImageView)?.sourceSizeOrNull() ?: return null
    val (sourceWidth, sourceHeight) = source
    if (sourceWidth <= 0 || sourceHeight <= 0) return null
    val sourceRect = capture.sourceRect
    val crop = mihon.data.ocr.SerializableNormalizedRect(
        left = sourceRect.left.toFloat() / sourceWidth,
        top = sourceRect.top.toFloat() / sourceHeight,
        right = sourceRect.right.toFloat() / sourceWidth,
        bottom = sourceRect.bottom.toFloat() / sourceHeight,
    )
    if (!crop.isUsable()) return null
    return AutoReadEngine.OcrFrameGeometry(
        sourceWidth = sourceWidth,
        sourceHeight = sourceHeight,
        crop = crop,
        // Прокрутка страницы: сколько её высоты осталось позади кадра.
        scrollFraction = crop.top,
    )
}

private suspend fun resolveSelectionCaptures(
    rect: android.graphics.RectF,
): List<ReaderSelectionCapture> {
    val screenRect = dialogRootRectToScreenRect(rect)
    val captures = withUIContext {
        val resolvedCaptures = viewModel.state.value.viewer?.resolveSelectionCaptures(
            ReaderSelectionRegion(screenRect = screenRect),
        )
        if (!resolvedCaptures.isNullOrEmpty()) {
            exitOcrMode()
        }
        resolvedCaptures
    }
        .orEmpty()

    if (captures.isNotEmpty()) {
        logcat(LogPriority.DEBUG) {
            "Selection resolved ${captures.size} capture(s) for screenRect=" +
                "${screenRect.left},${screenRect.top},${screenRect.right},${screenRect.bottom}"
        }
    }
    return captures
}

fun showOcrResult(selection: ReaderOcrRegionSelection) {
    if (!shouldHandleCachedOcrRegionTaps()) {
        return
    }

    if (shouldOpenCachedOcrResultInPopup()) {
        if (!openCachedOcrOverlaySession(selection)) {
            return
        }
    } else {
        clearActiveOcrOverlaySession()
    }

    viewModel.showOcrResult(
        queryText = selection.queryText,
        origin = ReaderViewModel.OcrResultOrigin.CachedPageTap,
        initialSearchText = searchTextForOffset(selection.queryText, selection.initialSelectionOffset),
        source = viewModel.currentOcrSource(),
    )
}

private fun shouldOpenCachedOcrResultInPopup(): Boolean {
    return dictionaryPreferences.ocrResultPresentation().get() == OcrResultPresentation.POPUP
}

private fun openCachedOcrOverlaySession(selection: ReaderOcrRegionSelection): Boolean {
    val anchorRect = selection.anchorRectOnScreen?.let(::screenRectToDialogRootRect) ?: return false
    if (activeOcrOverlaySession?.matches(selection) == true) {
        dismissActiveOcrOverlaySession()
        return false
    }

    activeOcrOverlaySession = ActiveOcrOverlaySession(
        selection = selection,
        anchorRectInDialogRoot = anchorRect,
    )
    return syncActiveOcrOverlay()

/**
 * Показ AI-чата книги. Живёт на уровне activity, а не внутри composable:
 * состояние должно пережить пересборку composable (поворот экрана, смена
 * главы) и открываться из разных точек — меню и авто-действий агента.
 */
private val aiChatVisible = kotlinx.coroutines.flow.MutableStateFlow(false)

/**
 * Реальная автопрокрутка вместо прежней тост-заглушки: вебтун плавно
 * скроллится, пейджер листает страницы с интервалом, зависящим от скорости.
 *
 * v1.9.137 — ПЕЙСИНГ С АВТОЧТЕНИЕМ: пока кадр сканируется/распознаётся/
 * озвучивается ([autoReadFrameBusy]), прокрутка СТОИТ — на большой скорости
 * глаза больше не убегают от голоса. А сама авточтение при старте сама
 * включает эту кнопку (см. startAutoReadLoop), а не свои «прыжки».
 */
@Volatile
private var autoReadFrameBusy = false

/** Автопрокрутку включила АВТОЧТЕНИЕ (снять при его остановке). */
@Volatile
private var autoscrollAutoEnabled = false

/** Последняя выбранная скорость — чтобы авто-включение шло с той же. */
private var lastAutoscrollSpeed = 2f

private fun toggleAutoscroll(active: Boolean, speed: Float) {
    autoscrollJob?.cancel()
    autoscrollJob = null
    if (active) lastAutoscrollSpeed = speed
    if (!active) return
    // repeatOnLifecycle, а не просто lifecycleScope: тот живёт до
    // onDestroy, поэтому после сворачивания приложения 60-Гц scrollBy
    // продолжал крутиться в фоне и есть всю батарею, пока читатель в
    // другом приложении. Цикл теперь живёт только в STARTED.
    autoscrollJob = lifecycleScope.launch {
        repeatOnLifecycle(Lifecycle.State.STARTED) {
            while (true) {
                when (val viewer = viewModel.state.value.viewer) {
                    is eu.kanade.tachiyomi.ui.reader.viewer.webtoon.WebtoonViewer -> {
                        // Пейсинг: кадр авточтения занят (скан/OCR/речь) —
                        // прокрутка ЗАМЕДЛЯЕТСЯ до трети скорости (v1.9.138:
                        // не полный стоп — лента чуть ползёт, глаз не бежит
                        // впереди голоса, но и картинка не застывает).
                        if (autoReadActive && autoReadFrameBusy) {
                            val slow = (speed / 3f).toInt().coerceAtLeast(1)
                            viewer.recycler.scrollBy(0, slow)
                            kotlinx.coroutines.delay(24)
                        } else {
                            // ~60 Гц; скорость 1..10 → 1..10 px за кадр
                            viewer.recycler.scrollBy(0, speed.toInt().coerceAtLeast(1))
                            kotlinx.coroutines.delay(16)
                        }
                    }
                    is eu.kanade.tachiyomi.ui.reader.viewer.pager.PagerViewer -> {
                        // Скорость 1..10 → пауза 11..2 сек на страницу
                        kotlinx.coroutines.delay((12_000L - speed.toLong() * 1_000L).coerceAtLeast(2_000L))
                        viewer.moveToNext()
                    }
                    else -> kotlinx.coroutines.delay(250)
                }
            }
        }
    }
}
