/**
 * Записи буфера, относящиеся к ЭТОЙ странице.
 *
 * Страница известна по [ocrPageIdentity] — тому же хуку, по которому
 * работает оверлей активной реплики, поэтому в пагере и в вебтуне (где
 * страниц в ленте много одновременно) пометки ложатся именно на ту
 * страницу, к которой относятся. Кэш по [OcrScreenshotBuffer.version]:
 * перерисовка идёт на каждом кадре анимации, фильтровать буфер заново
 * там незачем.
 */
private fun currentOcrPageMarks(): List<OcrScreenshotEntry>? {
    val identity = ocrPageIdentity ?: return null
    val version = OcrScreenshotBuffer.version
    val cache = ocrPageMarksCache
    if (cache != null && cache.identity == identity && cache.version == version) {
        return cache.entries
    }
    val entries = OcrScreenshotBuffer.forPage(identity.chapterId, identity.pageIndex)
        .filter { it.hasSourceGeometry }
    ocrPageMarksCache = OcrPageMarksCache(identity, version, entries)
    return entries
}

private fun drawActiveOcrOverlay(canvas: Canvas) {
    // Выключатель из Настройки → Распознавание: пользователь убирает
    // оверлей совсем, когда текст поверх страницы мешает читать картинку.
    if (!ocrPrefs.ocrPageTextOverlay().get()) return
    val overlayLayout = getOrBuildActiveOverlayLayout() ?: return
    // Подложка под текстом обязательна. Раньше её убрали («solid white
    // background box»), и на светлой странице белый текст поверх белой
    // бумаги просто исчезал — оверлей был, а прочитать его нельзя.
    // Заливка идёт по textRect (области текста), а не по всему
    // boundingBox, и полупрозрачная: картинка под ней остаётся видна.
    val pad = resources.displayMetrics.density * 4f
    val bg = RectF(overlayLayout.textRect).apply { inset(-pad, -pad) }
    val radius = resources.displayMetrics.density * 6f
    canvas.drawRoundRect(bg, radius, radius, ocrOverlayBackgroundPaint)
    canvas.drawRoundRect(bg, radius, radius, ocrOverlayStrokePaint)
    ocrOverlayRenderer.drawOverlay(canvas, overlayLayout)
}

private fun resolveInitialSelectionOffset(
    region: mihon.domain.ocr.model.OcrRegion,
    normalizedDisplayText: String,
    localX: Float,
    localY: Float,
): Int {
    val overlayLayout = ocrOverlayRenderer.buildLayout(
        bubbleRect = boundingBoxToLocalRect(region.boundingBox) ?: return 0,
        displayText = normalizedDisplayText,
        textOrientation = region.textOrientation,
        highlightRange = null,

                        text = it.text,
                        boundingBox = it.boundingBox,
                    )
                },
                OcrRegionRules.readingOrderFor(prefs),
            )
        }
        .orEmpty()

    val entry = OcrScreenshotBuffer.add(
        chapterId = chapterId,
        pageIndex = pageIndex,
        scrollFraction = geometry?.scrollFraction ?: scrollFraction,
        regions = ordered.mapIndexed { idx, line ->
            OcrRegion(
                order = idx,
                text = line.text,
                boundingBox = line.boundingBox,
                textOrientation = OcrTextOrientation.Horizontal,
            )
        },
        // Без OCR результата виноват выбранный движок — он и остаётся
        // подписью записи, чтобы читатель видел, каким движком снималось.
        engineUsed = (page?.ocrModel ?: prefs.ocrModel().get()).name.lowercase(),
        imageWidth = width,
        imageHeight = height,
        imageJpeg = jpeg,
        // Какая часть страницы попала в кадр: без этого координаты регионов
        // не вернуть на страницу (в книге по ним рисуются пометки чтения).
        sourceWidth = geometry?.sourceWidth ?: 0,
        sourceHeight = geometry?.sourceHeight ?: 0,
        scanCrop = geometry?.crop ?: SerializableNormalizedRect(),
    )
    if (entry.imagePath == null) {
        // JPEG не записался — записи с картинкой не будет, публиковать нечего.
        return ScreenshotResult.NotSaved("буфер скриншотов недоступен")
    }

    // Та же самая картинка в Pictures/Yomikai: без неё файл не видно ни в
    // галерее телефона, ни в «Файлах» — приватный filesDir наружу не отдаёт.
    val galleryUri = OcrScreenshotBuffer.publishToGallery(
        context = context,
        jpeg = jpeg,
        displayName = OcrScreenshotBuffer.galleryDisplayName(pageIndex),
    )
    return if (galleryUri != null) {
        ScreenshotResult.SavedInGallery(galleryUri)
    } else {
        ScreenshotResult.SavedInAppOnly("галерея недоступна")
    }
}

private fun Bitmap.toOcrImage(): OcrImage {
    val pixels = IntArray(width * height)
    getPixels(pixels, 0, width, 0, 0, width, height)
    return OcrImage(width, height, pixels)
}

